         }
         if assetJSON == nil {
             return fmt.Errorf("asset %s does not exist", assetID)
         }

         var asset Asset
         err = json.Unmarshal(assetJSON, &asset)
         if err != nil {
             return err
         }

         // Check if the caller is the current owner or an admin
         callerID, err := ctx.GetClientIdentity().GetID()
         if err != nil {
             return fmt.Errorf("failed to get caller ID: %v", err)
         }
         if asset.Owner != callerID && callerID != "admin" {
             return fmt.Errorf("caller is not the owner or an admin")
